/**
 * Exact port of `contracts/ebbflow/src/curve.rs`.
 *
 * Every function must return byte-identical results to the contract so the solver's
 * quotes match on-chain settlement. Parity is checked against fixtures generated by the
 * Rust tests (`fixtures/curve.json`).
 *
 * Prices are quote atomic units per one whole base token, scaled by `PRICE_SCALE`.
 * With `k = alpha + 1`, taking a fraction `x` of a side's base capacity moves the
 * marginal price along `p_c ± span * x^k`. Rounding always goes against the taker.
 */

export const PRICE_SCALE = 10n ** 12n;
export const FRAC = 10n ** 18n;
export const MAX_ALPHA = 3;
const U128_MAX = (1n << 128n) - 1n;

export type CurveErrorCode = "InvalidCurve" | "InsufficientLiquidity" | "ZeroAmount" | "Overflow";

export class CurveError extends Error {
  constructor(public readonly code: CurveErrorCode) {
    super(code);
    this.name = "CurveError";
  }
}

/** The remaining segment of one side of a position. `remaining` is base (ask) or quote (bid). */
export interface Side {
  remaining: bigint;
  start_price: bigint;
  current_price: bigint;
  end_price: bigint;
  alpha: number;
}

/** JSON form returned by the contract views (u128 as decimal strings). */
export interface SideJson {
  remaining: string;
  start_price: string;
  current_price: string;
  end_price: string;
  alpha: number;
}

export interface Fill {
  base: bigint;
  /** Ask: quote the taker pays. Bid: quote the taker receives. */
  quote: bigint;
  new_price: bigint;
}

export function sideFromJson(s: SideJson): Side {
  return {
    remaining: BigInt(s.remaining),
    start_price: BigInt(s.start_price),
    current_price: BigInt(s.current_price),
    end_price: BigInt(s.end_price),
    alpha: s.alpha,
  };
}

export function sideToJson(s: Side): SideJson {
  return {
    remaining: s.remaining.toString(),
    start_price: s.start_price.toString(),
    current_price: s.current_price.toString(),
    end_price: s.end_price.toString(),
    alpha: s.alpha,
  };
}

export function newSide(remaining: bigint, startPrice: bigint, endPrice: bigint, alpha: number): Side {
  return { remaining, start_price: startPrice, current_price: startPrice, end_price: endPrice, alpha };
}

export function validateAsk(s: Side): void {
  if (s.remaining === 0n || s.alpha > MAX_ALPHA || s.start_price === 0n || s.start_price > s.end_price) {
    throw new CurveError("InvalidCurve");
  }
}

export function validateBid(s: Side): void {
  if (s.remaining === 0n || s.alpha > MAX_ALPHA || s.end_price === 0n || s.start_price < s.end_price) {
    throw new CurveError("InvalidCurve");
  }
}

function divUp(a: bigint, b: bigint): bigint {
  return a % b === 0n ? a / b : a / b + 1n;
}

function toU128(x: bigint): bigint {
  if (x > U128_MAX) throw new CurveError("Overflow");
  return x;
}

/** `x^k` in FRAC fixed point, rounding up at every step. */
function powFracUp(x: bigint, k: number): bigint {
  let r = x;
  for (let i = 1; i < k; i++) r = divUp(r * x, FRAC);
  return r;
}

/** Quote value of `base` at `price`. */
export function value(base: bigint, price: bigint, baseUnit: bigint, roundUp: boolean): bigint {
  const num = base * price;
  const den = baseUnit * PRICE_SCALE;
  return toU128(roundUp ? divUp(num, den) : num / den);
}

/** Base an ask side can still sell. */
export function askCapacity(s: Side): bigint {
  return s.remaining;
}

/** Taker buys `base` from an ask side. Quote cost rounds up. */
export function askFill(s: Side, baseUnit: bigint, base: bigint): Fill {
  if (base === 0n) throw new CurveError("ZeroAmount");
  if (base > s.remaining) throw new CurveError("InsufficientLiquidity");
  const pc = s.current_price;
  const span = s.end_price - pc;
  const k = s.alpha + 1;
  const k1 = BigInt(k + 1);
  const xk = span === 0n ? 0n : powFracUp(divUp(base * FRAC, s.remaining), k);

  const num = base * (pc * FRAC * k1 + span * xk);
  const den = FRAC * k1 * baseUnit * PRICE_SCALE;
  const quote = toU128(divUp(num, den));

  let newPrice: bigint;
  if (base === s.remaining) {
    newPrice = s.end_price;
  } else {
    const step = toU128(divUp(span * xk, FRAC));
    newPrice = pc + step < s.end_price ? pc + step : s.end_price;
  }
  return { base, quote, new_price: newPrice };
}

/** Base a bid side can still buy if its whole remaining curve is consumed (rounded down). */
export function bidCapacity(s: Side, baseUnit: bigint): bigint {
  if (s.remaining === 0n) return 0n;
  const k = BigInt(s.alpha + 1);
  const span = s.current_price - s.end_price;
  const den = s.current_price * (k + 1n) - span;
  return toU128((s.remaining * baseUnit * PRICE_SCALE * (k + 1n)) / den);
}

/** Taker sells `base` into a bid side. Quote output rounds down. */
export function bidFill(s: Side, baseUnit: bigint, base: bigint): Fill {
  if (base === 0n) throw new CurveError("ZeroAmount");
  const cap = bidCapacity(s, baseUnit);
  if (base > cap) throw new CurveError("InsufficientLiquidity");
  const pc = s.current_price;
  const span = pc - s.end_price;
  const k = s.alpha + 1;
  const k1 = BigInt(k + 1);
  const xk = span === 0n ? 0n : powFracUp(divUp(base * FRAC, cap), k);

  const num = base * (pc * FRAC * k1 - span * xk);
  const den = FRAC * k1 * baseUnit * PRICE_SCALE;
  const raw = toU128(num / den);
  const quote = raw < s.remaining ? raw : s.remaining;

  let newPrice: bigint;
  if (base === cap) {
    newPrice = s.end_price;
  } else {
    const step = toU128(divUp(span * xk, FRAC));
    const p = pc > step ? pc - step : 0n;
    newPrice = p > s.end_price ? p : s.end_price;
  }
  return { base, quote, new_price: newPrice };
}

/** Applies a fill to a copy of the side (without recycling). */
export function applyAsk(s: Side, f: Fill): Side {
  return { ...s, remaining: s.remaining - f.base, current_price: f.new_price };
}

export function applyBid(s: Side, f: Fill): Side {
  return { ...s, remaining: s.remaining - f.quote, current_price: f.new_price };
}

// ---------- unit helpers ----------

/** "5.04" with 6 quote decimals -> scaled contract price. */
export function parsePrice(human: string, quoteDecimals: number): bigint {
  return parseUnits(human, quoteDecimals + 12);
}

/** Scaled contract price -> human decimal string. */
export function formatPrice(price: bigint, quoteDecimals: number, maxFraction = 6): string {
  return formatUnits(price, quoteDecimals + 12, maxFraction);
}

export function parseUnits(human: string, decimals: number): bigint {
  const m = /^(\d+)(?:\.(\d*))?$/.exec(human.trim());
  if (!m) throw new Error(`invalid amount: ${human}`);
  const whole = m[1] ?? "0";
  const frac = (m[2] ?? "").padEnd(decimals, "0");
  if (frac.length > decimals && /[1-9]/.test(frac.slice(decimals))) {
    throw new Error(`too many decimals in ${human} (max ${decimals})`);
  }
  return BigInt(whole) * 10n ** BigInt(decimals) + BigInt(frac.slice(0, decimals) || "0");
}

export function formatUnits(v: bigint, decimals: number, maxFraction = decimals): string {
  const neg = v < 0n;
  const a = neg ? -v : v;
  const unit = 10n ** BigInt(decimals);
  const whole = a / unit;
  let frac = (a % unit).toString().padStart(decimals, "0").slice(0, maxFraction).replace(/0+$/, "");
  return `${neg ? "-" : ""}${whole}${frac ? "." + frac : ""}`;
}
